    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    # Update donor reputation based on second-order norm:
    # Cooperation with good (rep >= 0) is good, with bad (rep < 0) is bad.
    # Defection against bad is good, against good is bad.
    step = 0.2
    if donor_action == 'cooperate':
        if recipient_reputation >= 0.0:
            new_rep = donor_reputation + step
        else:
            new_rep = donor_reputation - step
    else:  # defect
        if recipient_reputation < 0.0:
            new_rep = donor_reputation + step
        else:
            new_rep = donor_reputation - step
    # Clamp to [-1.0, 1.0]
    if new_rep > 1.0:
        new_rep = 1.0
    elif new_rep < -1.0:
        new_rep = -1.0
    return new_rep


