def evaluate(
    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    # Determine if recipient is considered 'good' (reputation > 0.0)
    recipient_good = recipient_reputation > 0.0

    # Reputation change based on donor action and recipient's goodness
    if donor_action == 'cooperate':
        if recipient_good:
            change = 0.12  # cooperation with good: positive (slightly larger)
        else:
            change = -0.1  # cooperation with bad: negative (unchanged)
    else:  # defect
        if recipient_good:
            change = -0.12  # defection against good: negative (slightly larger)
        else:
            change = 0.1   # defection against bad: positive (unchanged)

    # Add a small modulation based on the observer's own reputation
    # (only for negative changes, e.g., if self-rating is low, punishment is harsher)
    if change < 0 and my_reputation < -0.5:
        change *= 1.5  # amplify punishment for low-reputation observers
    elif change > 0 and my_reputation > 0.5:
        change *= 0.8  # slightly reduce reward for high-reputation observers

    # Apply change and clamp to [-1.0, 1.0]
    new_rating = donor_reputation + change
    return max(-1.0, min(1.0, new_rating))


